INSERT INTO `livro` (`cod_liv`, `titulo`, `autor`, `genero`, `editora`, `data_publi`, `estado`, `quantidade`, `v_compra`, `v_venda`, `descricao`, `foto`) VALUES
(1, 'O poder da Ação', 'Paulo Vieira', 'Auto ajuda', 'Gente', '2019-10-10', 'novo', 10, '45.90', '94.85', ' Aprenda a tomar as decisões certas • Saiba como obter respostas de sucesso • Reprograme sua mente • Desenvolva novas capacidades • Conquiste a vida que sempre quis em seis meses • Aumente suas competências financeiras e profissionais.', );
