(2, 'A Justiça', 'Platão', 'filosofia', 'edipro', '2005-02-01', 'usado', 1, '96.06', '129.90', 'Este diálogo foi extraído de A República, a mais traduzida, difundida, estudada e influente obra de Platão, consagrada como um dos mais expressivos textos de filosofia de todos os tempos! ', );
INSERT INTO `livro` (`cod_liv`, `titulo`, `autor`, `genero`, `editora`, `data_publi`, `estado`, `quantidade`, `v_compra`, `v_venda`, `descricao`, `foto`) VALUES
(3, 'A República', 'Platão', 'filosofia', 'Editora Lafonte', '2017-02-01', 'usado', 2, '40.00', '45.00', 'De caráter político, prega um Estado ideal governado por líderes justos, sábios e instruídos. Para Platão, o homem capaz de reunir essas qualidades seria o filósofo.', );
